solution.app.js:
// app.js: your first Express server. client.js starts it and sends it what you type in the terminal.
const express = require("express");

const app = express();

// the data: in memory for now, so it starts fresh every time the server does
const plants = [
  { id: 1, name: "Tulip", water: "weekly" },
  { id: 2, name: "Fern", water: "daily" },
  { id: 3, name: "Cactus", water: "monthly" },
];

app.get("/", (req, res) => {
  res.send("Hello from Express!");
});

app.get("/about", (req, res) => {
  res.send("Greenhouse: a small API about plants, built one ticket at a time.");
});

app.get("/api/plants", (req, res) => {
  res.json(plants);
});

app.get("/api/stats", (req, res) => {
  const byWater = {};
  for (const plant of plants) byWater[plant.water] = (byWater[plant.water] || 0) + 1;
  res.json({ count: plants.length, byWater });
});

app.listen(3000, () => console.log("Server running on http://localhost:3000"));

tickets.tests:
let r = await request("GET /api/plants");
assert(r.status === 200 && r.type === "application/json", "GET /api/plants answers JSON, labelled application/json");
assert(Array.isArray(r.json) && r.json.length === 3, "It's the array of three plants");
assert(r.json[0].name === "Tulip" && r.json[2].water === "monthly", "in order: Tulip first, Cactus (monthly) last");
r = await request("GET /api/stats");
assert(r.json && r.json.count === 3, 'GET /api/stats has "count": 3');
assert(r.json.byWater && r.json.byWater.weekly === 1 && r.json.byWater.daily === 1 && r.json.byWater.monthly === 1, "and byWater counts each kind of watering");
r = await request("GET /");
assert(r.text === "Hello from Express!", "The first routes still work");

