// app.js: your first Express server. client.js starts it and sends it what you type in the terminal.
const express = require("express");

const app = express();

// every request, logged when its answer has gone out
app.use((req, res, next) => {
  res.on("finish", () => console.log(`${req.method} ${req.originalUrl} ${res.statusCode}`));
  next();
});
app.use(express.json());

// the data: in memory for now, so it starts fresh every time the server does
const plants = [
  { id: 1, name: "Tulip", water: "weekly" },
  { id: 2, name: "Fern", water: "daily" },
  { id: 3, name: "Cactus", water: "monthly" },
];
let nextId = 4;
const WATER = ["daily", "weekly", "monthly"];

// what's wrong with a plant a client sent, or null. partial (PATCH): only check the fields it sent
function problem(body, partial = false) {
  if (!partial || "name" in body) {
    if (typeof body.name !== "string" || !body.name.trim()) return "name is required";
  }
  if (!partial || "water" in body) {
    if (!WATER.includes(body.water)) return "water must be daily, weekly or monthly";
  }
  return null;
}

// middleware: loads the plant named by :id into req.plant, or answers 404
function findPlant(req, res, next) {
  req.plant = plants.find((p) => p.id === Number(req.params.id));
  if (!req.plant) return res.status(404).json({ error: "Plant not found" });
  next();
}

// middleware factory: a check of the body, whole (POST, PUT) or partial (PATCH)
function validate(partial) {
  return (req, res, next) => {
    const bad = problem(req.body || {}, partial);
    if (bad) return res.status(400).json({ error: bad });
    next();
  };
}

app.get("/", (req, res) => {
  res.send("Hello from Express!");
});

app.get("/about", (req, res) => {
  res.send("Greenhouse: a small API about plants, built one ticket at a time.");
});

app.get("/hello/:name", (req, res) => {
  res.send(`Hello, ${req.params.name}!`);
});

// ?water=weekly  ?search=c  ?sort=name, in any combination
app.get("/api/plants", (req, res) => {
  let result = plants;
  if (req.query.water) result = result.filter((p) => p.water === req.query.water);
  if (req.query.search) {
    const text = req.query.search.toLowerCase();
    result = result.filter((p) => p.name.toLowerCase().includes(text));
  }
  if (req.query.sort === "name") result = [...result].sort((a, b) => a.name.localeCompare(b.name));
  res.json(result);
});

app.get("/api/plants/:id", findPlant, (req, res) => res.json(req.plant));

app.post("/api/plants", validate(false), (req, res) => {
  const plant = { id: nextId++, name: req.body.name.trim(), water: req.body.water };
  plants.push(plant);
  res.status(201).location(`/api/plants/${plant.id}`).json(plant);
});

app.put("/api/plants/:id", findPlant, validate(false), (req, res) => {
  req.plant.name = req.body.name.trim();
  req.plant.water = req.body.water;
  res.json(req.plant);
});

app.patch("/api/plants/:id", findPlant, validate(true), (req, res) => {
  if ("name" in req.body) req.plant.name = req.body.name.trim();
  if ("water" in req.body) req.plant.water = req.body.water;
  res.json(req.plant);
});

app.delete("/api/plants/:id", findPlant, (req, res) => {
  plants.splice(plants.indexOf(req.plant), 1);
  res.status(204).end();
});

app.get("/api/stats", (req, res) => {
  const byWater = {};
