function problem(body, partial = false) {
  if (!partial || "name" in body) {
    if (typeof body.name !== "string" || !body.name.trim()) return "name is required";
  }
  if (!partial || "water" in body) {
    if (!WATER.includes(body.water)) return "water must be daily, weekly or monthly";
  }
