await request("POST /api/tasks", { title: "Buy bulbs" });
await request("POST /api/tasks", { title: "Water ferns" });
assert(disk("tasks.json.tmp") === null && JSON.parse(disk("tasks.json")).length === 2, "save leaves no .tmp behind: it's renamed over tasks.json");
plug();
await run('POST /api/tasks {"title": "Lost in the cut"}');
await restart();
let r = await request("GET /api/tasks");
assert(r.json && r.json.length === 2 && r.json[1].title === "Water ferns", "The power goes out halfway through a save: only that change is lost, and both saved tasks are still there");
await tear("tasks.json");
r = await request("GET /api/tasks");
assert(r.status === 200 && Array.isArray(r.json) && r.json.length === 0, "A tasks.json damaged some other way doesn't stop the server: it starts with an empty list");
assert(disk("tasks.json.corrupt") !== null, "and the torn file is kept as tasks.json.corrupt, for a human to look at");
r = await request("POST /api/tasks", { title: "Start again" });
assert(r.status === 201 && JSON.parse(disk("tasks.json")).length === 1, "Saving works again straight away");

