await request("POST /api/links", { url: "https://garden.example/tulips" });
await request("GET /q0U");
await request("GET /q0U", undefined, { headers: { Referer: "https://news.example/item?id=7" } });
await request("GET /q0U", undefined, { headers: { Referer: "https://news.example/front" } });
let r = await request("GET /api/links/q0U");
assert(r.json && r.json.clicks === 3, "Three redirects, three clicks");
assert(r.json.referrers && r.json.referrers["news.example"] === 2 && r.json.referrers.direct === 1, 'Counted by where they came from: {"news.example": 2, "direct": 1}');
r = await request("GET /api/links/q0U");
assert(r.json.clicks === 3, "Reading the stats isn't a click");
r = await request("GET /q0U", undefined, { headers: { Referer: "not an address" } });
assert(r.status === 302, "A Referer that isn't a URL doesn't break the redirect");
r = await request("GET /api/links/q0U");
assert(r.json.referrers.direct === 2 && r.json.clicks === 4, "and counts as direct");
r = await request("POST /api/links", { url: "https://garden.example/roses" });
assert(r.json && r.json.clicks === 0 && JSON.stringify(r.json.referrers) === "{}", "A new link starts at 0 clicks and {} referrers");

