assert(r.status === 400 && r.json && r.json.error === "ttl must be a whole number of seconds, from 1 to a year", "ttl 0: 400");
r = await request("POST /api/links", { url: "https://garden.example/", ttl: "60" });
assert(r.status === 400, "ttl as a string: 400");
r = await request("POST /api/links", { url: "https://garden.example/", ttl: 1.5 });
assert(r.status === 400, "ttl must be whole: 400");
r = await request("POST /api/links", { url: "https://garden.example/roses" });
assert(r.json && !("expiresIn" in r.json), "A link with no ttl has no expiresIn");

