// app.js: Shortlink, a URL shortener. client.js starts it with require("./app").
const express = require("express");
const { encode } = require("./codes");

const app = express();
app.use(express.json());

const BASE = "http://localhost:3000";
// every link, by its code
const links = new Map();
// the number behind the next code: 100000 is "q0U" in base 62, so codes start at three characters
let counter = 100000;
// the code already made for each URL, so shortening the same URL again gives the same link
const byUrl = new Map();

// an error that carries the status to answer with, for the error handler at the bottom
function httpError(status, message) {
  const err = new Error(message);
  err.status = status;
  return err;
}

// a URL a client sent: it has to parse, and be http or https (never javascript: or file:). Answers it normalised
function checkUrl(url) {
  if (typeof url !== "string" || !url.trim()) throw httpError(400, "url is required");
  let u;
  try {
    u = new URL(url.trim());
  } catch (err) {
    throw httpError(400, "url must be a full http:// or https:// address");
  }
  if (u.protocol !== "http:" && u.protocol !== "https:") throw httpError(400, "url must be a full http:// or https:// address");
  return u.href;
}

// a link as clients see it
function view(link) {
  const v = { code: link.code, url: link.url, short: `${BASE}/${link.code}`, clicks: link.clicks, referrers: link.referrers };
  if (link.expiresAt) v.expiresIn = Math.max(0, Math.ceil((link.expiresAt - Date.now()) / 1000));
  return v;
}

// middleware: loads the link named by :code into req.link
function findLink(req, res, next) {
  req.link = links.get(req.params.code);
  if (!req.link) throw httpError(404, "Link not found");
  next();
}

// where a click came from: the Referer's host, or "direct" when there isn't one (typed, or from an app)
function source(req) {
  try {
    return new URL(req.get("Referer")).host;
  } catch (err) {
    return "direct";
  }
}

// an alias is a code the client picks: letters, digits and dashes. "api" is ours
const ALIAS = /^[A-Za-z0-9-]{3,30}$/;
const RESERVED = ["api"];

// the next code nobody has: skip any that an alias already took
function freshCode() {
  let code;
  do code = encode(counter++);
  while (links.has(code));
  return code;
}

const expired = (link) => !!link.expiresAt && Date.now() >= link.expiresAt;

app.post("/api/links", (req, res) => {
  const body = req.body || {};
  const url = checkUrl(body.url);
  if (body.ttl !== undefined && (!Number.isInteger(body.ttl) || body.ttl < 1 || body.ttl > 31536000)) {
    throw httpError(400, "ttl must be a whole number of seconds, from 1 to a year");
  }
  if (body.alias !== undefined) {
    if (typeof body.alias !== "string" || !ALIAS.test(body.alias)) throw httpError(400, "alias must be 3 to 30 letters, digits or dashes");
    if (RESERVED.includes(body.alias.toLowerCase())) throw httpError(400, `"${body.alias}" is reserved`);
    if (links.has(body.alias)) throw httpError(409, "That alias is taken");
  }
  // the same URL again, with nothing special asked for: the link it already has
  const plain = body.alias === undefined && body.ttl === undefined;
  if (plain && byUrl.has(url)) return res.json(view(links.get(byUrl.get(url))));
  const link = { code: body.alias || freshCode(), url, clicks: 0, referrers: {} };
  if (body.alias) link.custom = true;
  if (body.ttl) link.expiresAt = Date.now() + body.ttl * 1000;
  links.set(link.code, link);
  if (plain) byUrl.set(url, link.code);
  res.status(201).location(`/api/links/${link.code}`).json(view(link));
});

app.get("/api/links/:code", findLink, (req, res) => {
  res.json(view(req.link));
});

// the short link itself: send the browser on to the long URL
app.get("/:code", findLink, (req, res) => {
  if (expired(req.link)) throw httpError(410, "This link has expired");
  const from = source(req);
  req.link.clicks++;
  req.link.referrers[from] = (req.link.referrers[from] || 0) + 1;
  res.redirect(302, req.link.url);
});

// any other path: a JSON 404, like every other error here
app.use((req, res) => {
  throw httpError(404, "Not found");
});

// every error ends up here, as JSON
app.use((err, req, res, next) => {
  if (err.type === "entity.parse.failed") return res.status(400).json({ error: "Invalid JSON" });
  const status = err.status || 500;
  if (status >= 500) console.error(`${req.method} ${req.originalUrl} failed: ${err.message}`);
  res.status(status).json({ error: status >= 500 ? "Something went wrong" : err.message });
});

app.listen(3000, () => console.log("Shortlink on http://localhost:3000"));

