let counter = saved.counter;
// the code already made for each URL, rebuilt from the links: an index is something you can always make again
const byUrl = new Map();
for (const l of links.values()) if (!l.deleted && !l.custom && !l.expiresAt) byUrl.set(l.url, l.code);
const persist = () => store.save({ counter, links: [...links.values()] });

// an error that carries the status to answer with, for the error handler at the bottom
function httpError(status, message) {
  const err = new Error(message);
  err.status = status;
  return err;
}

// a URL a client sent: it has to parse, and be http or https (never javascript: or file:). Answers it normalised
function checkUrl(url) {
