// store.js: the links in links.json, with the counter that makes their codes. Saved whole, and atomically:
// write a new file beside the old one, then rename it over, so a power cut leaves one or the other, never half
const fs = require("fs");

const FILE = "links.json";
const empty = () => ({ counter: 100000, links: [] });

function load() {
  if (!fs.existsSync(FILE)) return empty();
  try {
    return JSON.parse(fs.readFileSync(FILE, "utf8"));
  } catch (err) {
    fs.renameSync(FILE, FILE + ".corrupt");
    console.error(`${FILE} couldn't be read, so it was moved to ${FILE}.corrupt and Shortlink started empty`);
    return empty();
  }
}

function save(state) {
  fs.writeFileSync(FILE + ".tmp", JSON.stringify(state) + "\n");
  fs.renameSync(FILE + ".tmp", FILE);
}

module.exports = { load, save };

