// express.js: Trellis, a web framework in the shape of Express.
// app.js uses it exactly as it would use the real thing: const express = require("./express").
const http = require("http");

const METHODS = ["get", "post", "put", "patch", "delete"];

// "/notes/:id" -> /^\/notes\/([^/]+)\/?$/ and the names of its holes, ["id"]
function compile(path) {
  const keys = [];
  const pattern = path
    .replace(/\/$/, "")
    .replace(/[.*+?^${}()|[\]\\]/g, "\\$&")
    .replace(/:(\w+)/g, (_, name) => {
      keys.push(name);
      return "([^/]+)";
    });
  return { re: new RegExp(`^${pattern}/?$`), keys };
}

// the helpers every handler finds on res, so nobody writes setHeader, JSON.stringify and end by hand
function helpers(res) {
  res.status = (code) => {
    res.statusCode = code;
    return res;
  };
  res.set = (name, value) => {
    res.setHeader(name, value);
    return res;
  };
  res.json = (data) => {
    if (!res.getHeader("Content-Type")) res.setHeader("Content-Type", "application/json; charset=utf-8");
    res.end(JSON.stringify(data));
    return res;
  };
  res.send = (body) => {
    if (body !== null && typeof body === "object" && !Buffer.isBuffer(body)) return res.json(body);
    if (!res.getHeader("Content-Type")) res.setHeader("Content-Type", "text/html; charset=utf-8");
    res.end(body === undefined ? "" : body);
    return res;
  };
}

function express() {
  const routes = [];   // { method, re, keys, handler }, in the order they were added

  // the app is a request handler: http.createServer(app) calls it for every request
  function app(req, res) {
    helpers(res);
    const url = new URL(req.url, "http://localhost");
    req.path = url.pathname;
    req.query = Object.fromEntries(url.searchParams);
    for (const route of routes) {
      if (route.method !== req.method) continue;
      const m = route.re.exec(req.path);
      if (!m) continue;
      req.params = {};
      route.keys.forEach((k, i) => { req.params[k] = decodeURIComponent(m[i + 1]); });
      return route.handler(req, res);
    }
    res.status(404).set("Content-Type", "text/plain; charset=utf-8").send(`Cannot ${req.method} ${req.path}`);
  }

  for (const m of METHODS) {
    app[m] = (path, handler) => {
      routes.push({ method: m.toUpperCase(), ...compile(path), handler });
      return app;
    };
  }

  app.listen = (...args) => http.createServer(app).listen(...args);

  return app;
}

module.exports = express;

solution.app.js:
// app.js: your server, on your own framework. client.js starts it with require("./app").
const express = require("./express");

const app = express();

const notes = [
  { id: 1, text: "buy tulip bulbs" },
  { id: 2, text: "water the trellis" },
];

app.get("/", (req, res) => res.send("hello from trellis"));
app.get("/health", (req, res) => res.send("ok"));

app.get("/notes", (req, res) => {
  const q = (req.query.q || "").toLowerCase();
  res.json(notes.filter((n) => n.text.toLowerCase().includes(q)));
});

app.get("/notes/:id", (req, res) => {
  const note = notes.find((n) => n.id === Number(req.params.id));
  if (!note) return res.status(404).json({ error: "no such note" });
  res.json(note);
});

app.listen(3000, () => console.log("listening on http://localhost:3000"));

tickets.tests:
const express = require("express");
const app = express();
app.get("/users/:id", (req, res) => res.json({ params: req.params, path: req.path }));
app.get("/users/:uid/posts/:pid", (req, res) => res.json(req.params));
app.get("/search", (req, res) => res.json(req.query));
app.listen(3001);
const at = { port: 3001 };
let r = await request("GET /users/42", undefined, at);
assert(r.status === 200 && r.json && r.json.params.id === "42", '/users/:id matches /users/42, and req.params.id is "42", a string');
assert(r.json.path === "/users/42", "req.path is the path without the query string");
r = await request("GET /users/42/", undefined, at);
assert(r.status === 200, "A trailing slash still matches, as in Express");
r = await request("GET /users/7/posts/9", undefined, at);
assert(r.json && r.json.uid === "7" && r.json.pid === "9", "Two holes, two params");
r = await request("GET /users/a%20b", undefined, at);
assert(r.json && r.json.params.id === "a b", 'Params are decoded: a%20b is "a b"');
r = await request("GET /users", undefined, at);
assert(r.status === 404, "/users leaves the hole empty: 404");
r = await request("GET /users/1/2", undefined, at);
assert(r.status === 404, "A param is one segment: /users/1/2 doesn't match /users/:id");
r = await request("GET /search?q=tulip&page=2", undefined, at);
assert(r.json && r.json.q === "tulip" && r.json.page === "2", "req.query holds the query string, as strings");
r = await request("GET /notes/2");
assert(r.status === 200 && r.json && r.json.text === "water the trellis", "GET /notes/2 is note 2");
r = await request("GET /notes/9");
assert(r.status === 404 && r.json && r.json.error === "no such note", 'GET /notes/9: 404 and {"error": "no such note"}');
r = await request("GET /notes?q=TULIP");
assert(r.json && r.json.length === 1 && r.json[0].id === 1, "GET /notes?q=TULIP searches, ignoring case");

