const express = require("express");
const app = express();
const seen = [];
app.use((req, res, next) => { seen.push("all"); next(); });
app.use("/admin", (req, res, next) => { seen.push("admin"); if (req.query.key !== "k") return res.status(401).send("no key"); next(); });
app.get("/admin/stats", (req, res) => res.send("stats"));
app.get("/two", (req, res, next) => { req.who = "first"; next(); }, (req, res) => res.send(req.who + " then second"));
app.get("/two", (req, res) => res.send("never"));
app.get("/skip", (req, res, next) => next());
app.listen(3001);
const at = { port: 3001 };
let r = await request("GET /two", undefined, at);
assert(r.text === "first then second", "A route can have several handlers: next() moves to the next one");
assert(seen.join() === "all", "app.use(fn) runs for every request, before the routes added after it");
r = await request("GET /admin/stats", undefined, at);
assert(r.status === 401 && seen.join() === "all,all,admin", "app.use('/admin', fn) runs for paths under /admin, and can answer and stop");
r = await request("GET /admin/stats?key=k", undefined, at);
assert(r.text === "stats", "or call next() and let the route answer");
seen.length = 0;
await request("GET /administrator", undefined, at);
assert(!seen.includes("admin"), "/administrator is not under /admin");
r = await request("GET /skip", undefined, at);
assert(r.status === 404 && r.text === "Cannot GET /skip", "When the last layer calls next(), it's a 404");
assert(app.use((req, res, next) => next()) === app, "app.use returns the app");
r = await request("GET /notes/1");
assert(r.json && r.json.text === "buy tulip bulbs", "The notes still work");
const shown = await run("GET /notes/9");
assert(shown.split("\n")[0] === "GET /notes/9 → 404", "app.js logs each request once it's answered: GET /notes/9 → 404");

